const ARMS_HERO_MODE = window.__AZEROT_ARMS_HERO__ === true;
const KEY = ARMS_HERO_MODE ? 'azeroth-arms-hero-v1' : 'azeroth-ab-setup-v5';
if (ARMS_HERO_MODE) {
